package litellm

import (
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"sync/atomic"
	"testing"

	"github.com/hashicorp/terraform-plugin-sdk/v2/helper/schema"
)

// newTestResourceData creates a *schema.ResourceData with the credential schema,
// sets the ID and populates the required fields.
func newTestResourceData(t *testing.T, id string) *schema.ResourceData {
	t.Helper()
	d := schema.TestResourceDataRaw(t, resourceLiteLLMCredential().Schema, map[string]interface{}{
		"credential_name":   id,
		"model_id":          "",
		"credential_info":   map[string]interface{}{},
		"credential_values": map[string]interface{}{"key": "val"},
	})
	d.SetId(id)
	return d
}

func TestRetryCredentialRead_SuccessOnFirstAttempt(t *testing.T) {
	resp := CredentialResponse{
		CredentialName: "test-cred",
		CredentialInfo: map[string]interface{}{"provider": "aws"},
	}
	body, _ := json.Marshal(resp)

	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusOK)
		w.Write(body)
	}))
	defer srv.Close()

	client := NewClient(srv.URL, "test-key", true)
	d := newTestResourceData(t, "test-cred")

	err := retryCredentialRead(d, client, 3)
	if err != nil {
		t.Fatalf("expected nil error, got: %v", err)
	}
	if d.Id() != "test-cred" {
		t.Fatalf("expected ID 'test-cred', got %q", d.Id())
	}
}

func TestRetryCredentialRead_SuccessAfterRetries(t *testing.T) {
	resp := CredentialResponse{
		CredentialName: "test-cred",
		CredentialInfo: map[string]interface{}{"provider": "aws"},
	}
	body, _ := json.Marshal(resp)

	var callCount int32
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		n := atomic.AddInt32(&callCount, 1)
		w.Header().Set("Content-Type", "application/json")
		if n <= 2 {
			// First two calls return 404, triggering retry
			w.WriteHeader(http.StatusNotFound)
			return
		}
		w.WriteHeader(http.StatusOK)
		w.Write(body)
	}))
	defer srv.Close()

	client := NewClient(srv.URL, "test-key", true)
	d := newTestResourceData(t, "test-cred")

	err := retryCredentialRead(d, client, 3)
	if err != nil {
		t.Fatalf("expected nil error, got: %v", err)
	}
	if d.Id() != "test-cred" {
		t.Fatalf("expected ID 'test-cred', got %q", d.Id())
	}
	if atomic.LoadInt32(&callCount) != 3 {
		t.Fatalf("expected 3 HTTP calls, got %d", callCount)
	}
}

func TestRetryCredentialRead_ExhaustsRetries(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusNotFound)
	}))
	defer srv.Close()

	client := NewClient(srv.URL, "test-key", true)
	d := newTestResourceData(t, "test-cred")

	err := retryCredentialRead(d, client, 2)
	if err == nil {
		t.Fatal("expected error after exhausting retries, got nil")
	}
	if err.Error() != "credential_not_found" {
		t.Fatalf("expected 'credential_not_found' error, got: %v", err)
	}
	// ID should still be restored (not wiped)
	if d.Id() != "test-cred" {
		t.Fatalf("expected ID to be restored to 'test-cred', got %q", d.Id())
	}
}

func TestRetryCredentialRead_NonRetryableError(t *testing.T) {
	var callCount int32
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		atomic.AddInt32(&callCount, 1)
		w.WriteHeader(http.StatusInternalServerError)
		w.Write([]byte(`{"error": "internal server error"}`))
	}))
	defer srv.Close()

	client := NewClient(srv.URL, "test-key", true)
	d := newTestResourceData(t, "test-cred")

	err := retryCredentialRead(d, client, 3)
	if err == nil {
		t.Fatal("expected error for 500 response, got nil")
	}
	// Should fail on first attempt without retrying
	if atomic.LoadInt32(&callCount) != 1 {
		t.Fatalf("expected 1 HTTP call (no retries for non-retryable error), got %d", callCount)
	}
}

func TestRetryCredentialRead_IDRestoredBetweenRetries(t *testing.T) {
	// Verify the ID is restored after each failed attempt where the read clears it.
	// resourceLiteLLMCredentialRead sets ID to "" on 404, and retryCredentialRead
	// should restore it before the next attempt.
	resp := CredentialResponse{
		CredentialName: "my-cred",
		CredentialInfo: map[string]interface{}{},
	}
	body, _ := json.Marshal(resp)

	var callCount int32
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		n := atomic.AddInt32(&callCount, 1)
		w.Header().Set("Content-Type", "application/json")
		if n == 1 {
			w.WriteHeader(http.StatusNotFound)
			return
		}
		w.WriteHeader(http.StatusOK)
		w.Write(body)
	}))
	defer srv.Close()

	client := NewClient(srv.URL, "test-key", true)
	d := newTestResourceData(t, "my-cred")

	err := retryCredentialRead(d, client, 2)
	if err != nil {
		t.Fatalf("expected nil error, got: %v", err)
	}
	if d.Id() != "my-cred" {
		t.Fatalf("expected ID 'my-cred', got %q", d.Id())
	}
}

func TestRetryCredentialRead_MaxRetriesOne(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusNotFound)
	}))
	defer srv.Close()

	client := NewClient(srv.URL, "test-key", true)
	d := newTestResourceData(t, "test-cred")

	err := retryCredentialRead(d, client, 1)
	if err == nil {
		t.Fatal("expected error with maxRetries=1 and always-404, got nil")
	}
	if err.Error() != "credential_not_found" {
		t.Fatalf("expected 'credential_not_found', got: %v", err)
	}
}

func TestRetryCredentialRead_ConnectionError(t *testing.T) {
	// Point to a server that's already closed to simulate connection failure
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {}))
	srv.Close()

	client := NewClient(srv.URL, "test-key", true)
	d := newTestResourceData(t, "test-cred")

	err := retryCredentialRead(d, client, 1)
	if err == nil {
		t.Fatal("expected error for connection failure, got nil")
	}
	// Connection error should not be retried (not a "credential_not_found")
	fmt.Printf("connection error (expected): %v\n", err)
}

from litellm.litellm_core_utils.cloud_storage_security import (
    is_managed_cloud_storage_uri,
)


def test_is_managed_cloud_storage_uri_detects_raw_object_uris():
    assert is_managed_cloud_storage_uri("s3://bucket/litellm-batch-outputs/x.jsonl.out")
    assert is_managed_cloud_storage_uri("gs://bucket/litellm-vertex-files/x")


def test_is_managed_cloud_storage_uri_ignores_provider_and_unified_ids():
    # Plain provider ids and base64 unified ids carry no storage scheme.
    assert not is_managed_cloud_storage_uri("file-abc123")
    assert not is_managed_cloud_storage_uri("bGl0ZWxsbV9wcm94eQ==")
    assert not is_managed_cloud_storage_uri("")

"""Tests for the cache codec: encrypt on encode, drop the refresh_token, round-trip the bearer."""

from litellm.proxy._experimental.mcp_server.outbound_credentials.oauth_token_store import (
    OAuthToken,
)
from litellm.proxy._experimental.mcp_server.outbound_credentials.token_cache_codec import (
    OAuthTokenCacheCodec,
)


def _wrapping_codec():
    # A reversible stand-in for NaCl: proves encode() encrypts (output is wrapped) and decode()
    # decrypts, without needing a salt key.
    return OAuthTokenCacheCodec(
        encrypt=lambda s: f"enc:{s}",
        decrypt=lambda b: b[4:] if b.startswith("enc:") else None,
    )


def test_round_trips_the_access_token():
    codec = _wrapping_codec()
    token = codec.decode(
        codec.encode(OAuthToken(access_token="at-123", expires_at=1234.5))
    )
    assert token is not None
    assert token.access_token == "at-123"


def test_encode_encrypts_and_omits_the_refresh_token():
    codec = _wrapping_codec()
    blob = codec.encode(OAuthToken(access_token="at", refresh_token="super-secret-rt"))
    assert blob.startswith("enc:")  # encryption was applied
    assert (
        "super-secret-rt" not in blob
    )  # the long-lived secret never reaches the cache
    decoded = codec.decode(blob)
    assert decoded is not None and decoded.refresh_token is None


def test_decoded_token_defers_expiry_to_the_cache_ttl():
    codec = _wrapping_codec()
    token = codec.decode(codec.encode(OAuthToken(access_token="at", expires_at=999.0)))
    # The value carries no expiry; the cache entry's TTL bounds its life instead.
    assert token is not None and token.expires_at is None


def test_undecryptable_blob_is_a_miss():
    # e.g. master-key rotation makes an old entry unreadable -> treat as a miss, not a crash.
    assert _wrapping_codec().decode("not-our-prefix") is None


def test_empty_plaintext_is_a_miss():
    codec = OAuthTokenCacheCodec(encrypt=lambda s: s, decrypt=lambda b: b)
    assert codec.decode("") is None
